class Wallet:
    def __init__(self, balance):
        self.balance = balance

class Customer:
    def __init__(self, name, wallet):
        self.name = name
        self.wallet = wallet

    def can_afford(self, amount):
        return self.wallet.balance >= amount

def place_order(customer, total):
    if customer.wallet.balance >= total:
        return f"Order placed for {customer.name}"
    return "Not enough funds"

ana = Customer("Ana", Wallet(12))
print(place_order(ana, 9))

class Invoice:
    def __init__(self, lines):
        self.lines = lines

    def total(self):
        return sum(qty * price for qty, price in self.lines)

    def to_html(self):
        rows = "".join(f"<tr><td>{q}</td><td>{p:.2f}</td></tr>" for q, p in self.lines)
        return f"<table>{rows}</table>"

    def total_with_tax(self, rate):
        return round(self.total() * (1 + rate), 2)

inv = Invoice([(2, 3.50), (1, 4.25)])
print(inv.total_with_tax(0.1))

