from typing import Protocol

class OrderRepository(Protocol):
    def save(self, order: dict) -> int: ...

class InMemoryOrders:
    def __init__(self):
        self.rows = []

    def save(self, order):
        self.rows.append(order)
        return len(self.rows)

def place_order(repo: OrderRepository, items):
    total = sum(items.values())
    order_id = repo.save({"items": items, "total": total})
    return f"#{order_id}: {total}"

repo = InMemoryOrders()
print(place_order(repo, {"croissant": 3, "latte": 4}))
print(place_order(repo, {"bagel": 2}))
print(len(repo.rows))

class Order:
    MAX_ITEMS = 20

    def __init__(self):
        self.lines = []
        self.paid = False

    def add(self, item, qty):
        if self.paid:
            raise ValueError("order already paid")
        if self.count() + qty > self.MAX_ITEMS:
            raise ValueError("too many items")
        self.lines.append((item, qty))

    def pay(self):
        self.paid = True

    def count(self):
        return sum(qty for _, qty in self.lines)

order = Order()
order.add("croissant", 12)
order.pay()
order.lines.append(("bagel", 30))
print(order.count(), order.paid)

