import ast

sources = {
    "domain/order.py": "from decimal import Decimal\n",
    "domain/pricing.py": "import psycopg\nfrom domain.order import Order\n",
    "adapters/db.py": "import psycopg\nfrom domain.order import Order\n",
}

FORBIDDEN = {"psycopg", "flask", "adapters"}

def imported_roots(code):
    for node in ast.walk(ast.parse(code)):
        if isinstance(node, ast.Import):
            yield from (a.name.split(".")[0] for a in node.names)
        elif isinstance(node, ast.ImportFrom):
            yield node.module.split(".")[0]

for path, code in sources.items():
    if path.startswith("domain/"):
        bad = sorted(set(imported_roots(code)) & FORBIDDEN)
        print(path, "FAIL" if bad else "ok", bad)

import datetime

def is_happy_hour(now=None):
    now = now or datetime.datetime.now()
    return 15 <= now.hour < 17

def at(hour, minute=0):
    return datetime.datetime(2026, 10, 6, hour, minute)

print(is_happy_hour(at(16, 30)), is_happy_hour(at(17)), is_happy_hour(at(14, 59)))
